const j = $('Joiner fields').first().json;

// --- defensive parse of the model output; any failure falls back to the manual-fill placeholder ---
let llm = { matched: false, role_family: '', tool_bundle: '', who_to_meet: '', plan_owner: '' };
try {
  const src = $input.first().json;
  const raw = String(src.text || src.response || '');
  const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  if (s !== -1 && e > s) {
    const p = JSON.parse(cleaned.slice(s, e + 1));
    if (p && p.matched === true) {
      llm = {
        matched: true,
        role_family: String(p.role_family || ''),
        tool_bundle: String(p.tool_bundle || ''),
        who_to_meet: String(p.who_to_meet || ''),
        plan_owner: String(p.plan_owner || '')
      };
    }
  }
} catch (err) {
  llm.matched = false;
}
if (llm.matched && (!llm.tool_bundle || !llm.who_to_meet)) { llm.matched = false; }

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const mention = (id) => '<ac:link><ri:user ri:account-id="' + id + '" /></ac:link>';
const status = (colour, title) => '<ac:structured-macro ac:name="status"><ac:parameter ac:name="title">' + title + '</ac:parameter><ac:parameter ac:name="colour">' + colour + '</ac:parameter></ac:structured-macro>';
const task = (body) => '<ac:task><ac:task-status>incomplete</ac:task-status><ac:task-body>' + body + '</ac:task-body></ac:task>';

const RAUL = mention('712020:624f795f-6386-4939-8256-d6d78480c1d9');
const ANTONIO = mention('712020:3a258451-4f5c-45d0-bd88-474fb0e96165');
const EDYTA = mention('712020:3d299f3b-bedf-4226-ab54-25614a995669');
const NEEDS = '<strong>OWNER NEEDS TO BE ASSIGNED</strong>';
const TPL = 'https://futuremedia.atlassian.net/wiki/spaces/FGT/pages/1754693643';
const IT = 'https://futuremedia.atlassian.net/servicedesk/customer/portal/4/group/9/create/30';

const startCell = j.hired_on ? '<time datetime="' + esc(j.hired_on) + '" />' : '<strong>TBC</strong>';

const roleRef = llm.matched
  ? '<p><strong>Role reference:</strong> see the <strong>' + esc(llm.role_family) + '</strong> row of the <a href="' + TPL + '">Role Template</a> for the tool bundle (' + esc(llm.tool_bundle) + ') and who to meet (' + esc(llm.who_to_meet) + '). <strong>2-week plan owner:</strong> ' + (esc(llm.plan_owner) || 'NEEDS TO BE ASSIGNED') + '.</p>'
  : '<p><strong>Role reference:</strong> <strong>ROLE ROW NOT MATCHED — NEEDS MANUAL FILL.</strong> No row of the <a href="' + TPL + '">Role Template</a> clearly matches "' + esc(j.role) + '" in "' + esc(j.department) + '". Fill in the tool bundle, the who-to-meet list and the 2-week plan owner by hand.</p>';

const checklist = [
  'Role identified in the matrix (<a href="' + TPL + '">Role Template</a>) and all the info properly added/confirmed. ' + RAUL + ' · ETA:',
  'Tool bundle requested via <a href="' + IT + '">IT portal</a> + Access granted (' + ANTONIO + ' / ' + RAUL + ') - Verified ready before Day 1 — hard rule (' + ANTONIO + ' ' + RAUL + ') · ETA:',
  'Welcome email sent by HR to the joiner (' + EDYTA + ') · ETA:',
  '&quot;New Team Member Onboarding&quot; Slack canvas updated with role ad-hoc info and sent by HR (' + EDYTA + ') · ETA:',
  '2-week plan ready — see the plan below on this page — hard rule: no plan, no start date · written by ' + NEEDS + ' · sent to joiner by ' + EDYTA + ' · ETA:',
  'Baseline meetings scheduled: ' + EDYTA + ' (HR) · ETA:',
  'Role-specific meetings scheduled: ' + EDYTA + ' (HR) · ETA:',
  'Day-1 access verification call + 1st day tasks done — joiner clicks through every tool live and shows the changes done on Slack/PeopleForce ' + ANTONIO + ' / ' + RAUL + ' · ETA:',
  'End-of-week-2 review booked ' + NEEDS + ' (2-week plan owner) · ETA:'
];

const value =
  '<p><strong>Person:</strong> ' + esc(j.full_name) + ' · <strong>Role:</strong> ' + (esc(j.role) || 'TBC') + ' · <strong>Department:</strong> ' + (esc(j.department) || 'TBC') + ' · <strong>Start date of full time collaboration:</strong> ' + startCell + ' · ' + status('Yellow', 'IN PROGRESS') + '</p>' +
  '<p><strong>Email:</strong> <a href="mailto:' + esc(j.email) + '">' + esc(j.email) + '</a></p>' +
  '<ac:structured-macro ac:name="info"><ac:rich-text-body>' + roleRef + '</ac:rich-text-body></ac:structured-macro>' +
  '<h2>Onboarding checklist</h2>' +
  '<ac:task-list>' + checklist.map(task).join('') + '</ac:task-list>' +
  '<h2>2-week plan</h2>' +
  '<ac:structured-macro ac:name="note"><ac:rich-text-body><p>' + status('Red', 'PENDING') + ' No 2-week plan yet — <strong>hard rule: no plan, no start date.</strong> Paste the plan here once written (owner: ' + NEEDS + ').</p></ac:rich-text-body></ac:structured-macro>';

return [{
  json: {
    page_title: j.page_title,
    role_matched: llm.matched,
    pagePayload: {
      spaceId: '374538248',
      status: 'current',
      title: j.page_title,
      parentId: '1800765450',
      body: { representation: 'storage', value: value }
    }
  }
}];

